CREATE TABLE eaif_providers (id uuid PRIMARY KEY,tenant_id uuid NOT NULL,provider_code varchar(80) NOT NULL,display_name varchar(160) NOT NULL,provider_type varchar(40) NOT NULL,endpoint_url varchar(500),credential_reference varchar(300),enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL,created_by varchar(150) NOT NULL,updated_at timestamptz NOT NULL,updated_by varchar(150) NOT NULL,version bigint NOT NULL DEFAULT 0,status varchar(20) NOT NULL,CONSTRAINT uq_eaif_provider_code UNIQUE(tenant_id,provider_code));
CREATE TABLE eaif_models (id uuid PRIMARY KEY,tenant_id uuid NOT NULL,model_code varchar(100) NOT NULL,provider_code varchar(80) NOT NULL,provider_model varchar(180) NOT NULL,capability varchar(40) NOT NULL,max_input_tokens integer,max_output_tokens integer,enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL,created_by varchar(150) NOT NULL,updated_at timestamptz NOT NULL,updated_by varchar(150) NOT NULL,version bigint NOT NULL DEFAULT 0,status varchar(20) NOT NULL,CONSTRAINT uq_eaif_model_code UNIQUE(tenant_id,model_code));
CREATE TABLE eaif_prompt_templates (id uuid PRIMARY KEY,tenant_id uuid NOT NULL,template_code varchar(100) NOT NULL,template_version integer NOT NULL,system_prompt text,user_template text NOT NULL,variables_json text NOT NULL DEFAULT '[]',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL,created_by varchar(150) NOT NULL,updated_at timestamptz NOT NULL,updated_by varchar(150) NOT NULL,version bigint NOT NULL DEFAULT 0,status varchar(20) NOT NULL,CONSTRAINT uq_eaif_prompt_version UNIQUE(tenant_id,template_code,template_version));
CREATE TABLE eaif_requests (id uuid PRIMARY KEY,tenant_id uuid NOT NULL,source_service varchar(100) NOT NULL,use_case varchar(160) NOT NULL,model_code varchar(100) NOT NULL,prompt_template_code varchar(100),input_reference varchar(500),input_hash varchar(64) NOT NULL,risk_level varchar(20) NOT NULL,request_status varchar(30) NOT NULL,correlation_id varchar(100),output_reference varchar(500),failure_reason text,completed_at timestamptz,created_at timestamptz NOT NULL,created_by varchar(150) NOT NULL,updated_at timestamptz NOT NULL,updated_by varchar(150) NOT NULL,version bigint NOT NULL DEFAULT 0,status varchar(20) NOT NULL);
CREATE INDEX ix_eaif_request_status ON eaif_requests(tenant_id,request_status,created_at);
CREATE INDEX ix_eaif_request_source ON eaif_requests(tenant_id,source_service,correlation_id);
